-- Proof: Cindra is a REAL ribbon planet generated by the MAP-GEN itself, now a full
-- left->right ZONED gradient (ci-3yl worldgen; ci-da2 zone rework).
--
-- No on_chunk_generated script paints or voids anything. This drives the actual
-- planet map_gen_settings on a fresh, fixed-seed surface and proves, on the default
-- vertical orientation (ribbon long axis = Y; hot-cold gradient = X, hot on the
-- LEFT / west, perp = -x):
--   1. FINITE PERPENDICULAR: the map-gen's own `width` = the SUM of the zone widths
--      voids everything beyond the band (out-of-map); the interior is playable.
--   2. ZONED TILE GRADIENT: the ground is Cindra's own `cindra-*` tiles laid out
--      hot-lava -> lava -> lava-crust -> ... -> building -> ... -> deep-ice across
--      the X axis at the per-zone widths, with ORGANIC (wavy) boundaries.
--   3. WALKABILITY: the two hot lava zones are impassable; every other zone is
--      buildable ground (you can place on the lethal lava-crust / deep-ice edges).
--   4. DAMAGE FLAGS: the hot lava zones + lava-crust are heat-lethal; deep-ice is
--      cold-lethal; the middle is safe.
--   5. ZERO NAUVIS LEAKAGE: no grass, no water anywhere.
--   6. NATIVE RESOURCES: stone on the hot ribbon, ice on the cold cap, never crossed.
--   7. BAND-WIDE BOOTSTRAP ROCKS across the building band (finite per-rock).
--
-- The pure zone geometry is proven in unit-tests/test_terrain + test_resource_field;
-- this proves it actually generates on a live surface.

local field = require("scripts.resource-field")
local terrain = require("scripts.terrain")

describe("cindra worldgen: a real zoned left->right ribbon planet (§4; ci-da2)", function()
  -- A dedicated surface cloned from the Cindra planet's own map_gen_settings (same
  -- finite width, tile zones, resource controls) at a FIXED seed, so generation is
  -- reproducible and isolated from tests that pave/trample the shared "cindra"
  -- surface. The zone bands use fixed noise seeds, so they are seed-independent; the
  -- fixed seed pins the resource patches.
  local s
  local ready = false
  -- The default ribbon is 900 wide (x in [-450, 450]); sample resources over a
  -- long-axis span wide enough to catch the sparse spot-noise patches out on the
  -- cold cap (whose band excludes the origin's guaranteed starting patch).
  local RY = 300

  before_each(function()
    if ready then return end
    local base = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mgs = base.map_gen_settings
    mgs.seed = 2468
    -- The finite perpendicular bound is applied to a Cindra surface when it is
    -- created (scripts/driver.enforce_finite, since planet prototypes ignore width).
    -- This dedicated surface isn't named "cindra", so replicate the hook exactly.
    local fd = terrain.finite_dimension()
    mgs[fd.key] = fd.value
    s = game.surfaces["cindra-worldgen-test"] or game.create_surface("cindra-worldgen-test", mgs)
    -- Radius 18 chunks (~576 tiles) covers the full x in [-450,450] out to y ~= +/-RY
    -- (the far cold-cap corner at (450, 300) is ~541 tiles from the origin).
    s.request_to_generate_chunks({ 0, 0 }, 18)
    s.force_generate_chunk_requests()
    ready = true
  end)

  local function tile(x, y) return s.get_tile(x, y).name end

  -- The zone tile expected at the CENTRE of each zone's X band (default widths). The
  -- gradient is centred on the origin: hot (lava) west (negative x), cold (ice) east.
  local ZONE_AT = {
    { -425, "cindra-hot-lava" },
    { -375, "cindra-lava" },
    { -325, "cindra-lava-crust" },
    { -275, "cindra-volcanic-warm" },
    { -225, "cindra-basalt" },
    { -175, "cindra-scorched-dirt" },
    { -125, "cindra-dry-sand" },
    { 0,    "cindra-terminator" },
    { 125,  "cindra-cold-dust" },
    { 175,  "cindra-rough-ice" },
    { 325,  "cindra-deep-ice" },
  }

  -- 1. FINITE PERPENDICULAR via the map-gen (width = sum of zone widths) ----------
  it("is finite perpendicular: the map-gen voids beyond the total width, interior playable", function()
    -- width = 900 by default -> playable X is roughly [-450, 450].
    assert.are.equal("out-of-map", tile(-460, 0), "sunward (west) beyond the ribbon is void")
    assert.are.equal("out-of-map", tile(460, 0), "nightward (east) beyond the ribbon is void")
    assert.are_not.equal("out-of-map", tile(0, 0), "the building centre is playable")
    assert.are_not.equal("out-of-map", tile(-425, 0), "the hot-lava edge is still land")
    assert.are_not.equal("out-of-map", tile(425, 0), "the cold-ice edge is still land")
  end)

  -- 2. ZONED TILE GRADIENT, hot -> cold across the X axis, at the per-zone widths --
  it("lays the eleven zone tiles hot-lava -> ... -> building -> ... -> deep-ice", function()
    -- Sample the centre of each zone's band at a few long-axis rows; the noise
    -- wiggle (+/-7) never reaches a zone centre, so membership is exact.
    for _, zy in ipairs({ -120, 0, 120 }) do
      for _, z in ipairs(ZONE_AT) do
        local x, want = z[1], z[2]
        assert.are.equal(want, tile(x, zy),
          "zone tile at x=" .. x .. " y=" .. zy .. " should be " .. want)
      end
    end
  end)

  it("ALWAYS generates the hot-lava layer at the sunward edge (ci-a35)", function()
    -- The hottest zone must always exist at the far west edge, min width > 0.
    local hot = s.count_tiles_filtered({
      name = "cindra-hot-lava", area = { { -450, -RY }, { -395, RY } } })
    assert.is_true(hot > 0, "the sunward hot-lava band always generates")
  end)

  it("draws ORGANIC (wavy) zone boundaries, never raw straight lines", function()
    -- Scan the volcanic-warm -> basalt boundary (x ~= -250) across many Y rows: the
    -- X at which basalt first appears scanning east. A straight line => identical X
    -- on every row; the basis-noise wiggle makes it VARY.
    local first_basalt = {}
    for y = -160, 160, 16 do
      for x = -300, -200 do
        if tile(x, y) == "cindra-basalt" then first_basalt[#first_basalt + 1] = x; break end
      end
    end
    assert.is_true(#first_basalt >= 8, "sampled enough rows to judge the boundary")
    local lo, hi = first_basalt[1], first_basalt[1]
    for _, x in ipairs(first_basalt) do
      if x < lo then lo = x end
      if x > hi then hi = x end
    end
    assert.is_true(hi - lo >= 3,
      "the basalt boundary wanders across rows (organic); spread=" .. tostring(hi - lo))
  end)

  -- 3. WALKABILITY: the two hot lava zones impassable, everything else buildable ---
  it("makes the two hot lava zones impassable and every other zone buildable ground", function()
    -- Pave a deterministic patch of each zone tile far from the gradient and test
    -- whether a standard building can be placed (impassable lava blocks it).
    local function pave(name, cx, cy)
      local tiles = {}
      for x = cx - 4, cx + 4 do
        for y = cy - 4, cy + 4 do tiles[#tiles + 1] = { name = name, position = { x, y } } end
      end
      s.set_tiles(tiles, true)
    end
    local WY = 2600
    local function buildable(name)
      pave(name, 0, WY)
      return s.can_place_entity({ name = "stone-furnace", position = { 0, WY } })
    end
    assert.is_false(buildable("cindra-hot-lava"), "hot-lava is impassable (unbuildable)")
    assert.is_false(buildable("cindra-lava"), "lava is impassable (unbuildable)")
    for _, walk in ipairs({ "cindra-lava-crust", "cindra-volcanic-warm", "cindra-terminator",
                            "cindra-cold-dust", "cindra-rough-ice", "cindra-deep-ice" }) do
      assert.is_true(buildable(walk), walk .. " is buildable ground")
    end
  end)

  -- 4. DAMAGE FLAGS: hot lava zones + lava-crust heat, deep-ice cold, middle safe --
  it("flags the damage tiles: hot lava zones + lava-crust (heat), deep-ice (cold)", function()
    -- The generated tiles carry the runtime damage kind terrain.lethal_kind reports;
    -- tests/test_tile_damage proves the sweep actually bites. Here: the flags match.
    assert.are.equal("heat", terrain.lethal_kind(tile(-425, 0)), "hot-lava is heat-lethal")
    assert.are.equal("heat", terrain.lethal_kind(tile(-375, 0)), "lava is heat-lethal")
    assert.are.equal("heat", terrain.lethal_kind(tile(-325, 0)), "lava-crust is heat-lethal")
    assert.are.equal("cold", terrain.lethal_kind(tile(325, 0)), "deep-ice is cold-lethal")
    -- The building centre + a warm middle zone are safe.
    assert.is_nil(terrain.lethal_kind(tile(0, 0)), "the building centre is safe")
    assert.is_nil(terrain.lethal_kind(tile(-275, 0)), "volcanic-warm is safe")
  end)

  -- 5. ZERO NAUVIS LEAKAGE --------------------------------------------------------
  it("generates NO grass and NO water anywhere (no nauvis terrain leakage)", function()
    local box = { { -440, -RY }, { 440, RY } }
    for _, n in ipairs({ "grass-1", "grass-2", "grass-3", "grass-4", "water", "deepwater" }) do
      assert.are.equal(0, s.count_tiles_filtered({ name = n, area = box }),
        "Cindra must generate no " .. n)
    end
  end)

  it("paints ONLY Cindra tiles across the interior (every point is a cindra-* tile)", function()
    local cindra_set = {}
    for _, n in ipairs(terrain.tile_names()) do cindra_set[n] = true end
    for x = -440, 440, 40 do
      for y = -120, 120, 60 do
        local n = tile(x, y)
        assert.is_true(cindra_set[n] == true,
          "interior tile at (" .. x .. "," .. y .. ") must be a Cindra tile, got " .. n)
      end
    end
  end)

  -- 6. NATIVE RESOURCES, banded to the zones --------------------------------------
  local function count(name, x1, x2)
    return s.count_entities_filtered({ name = name, area = { { x1, -RY }, { x2, RY } } })
  end

  it("places stone on the building ribbon + hot margin, never on the cold cap", function()
    -- stone zone perp [-100, 350] -> x in [-350, 100].
    assert.is_true(count(field.STONE, -350, 100) > 0, "stone patches on the hot ribbon")
    assert.are.equal(0, count(field.STONE, 110, 450), "no stone on the cold cap (east)")
  end)

  it("places ice on the cold cap, never on the hot/temperate ribbon", function()
    -- ice zone perp [-450, -100) -> x in (100, 450].
    assert.is_true(count(field.ICE, 110, 450) > 0, "ice patches on the cold cap (east)")
    assert.are.equal(0, count(field.ICE, -350, 100), "no ice on the hot/temperate ribbon")
  end)

  -- 6a. ZONE PURITY (ci-7w0), proven on the LIVE map: STONE never in the cold zone,
  -- ICE never in the hot/temperate zone, and the TILE zones obey the same split.
  local function count_tiles(names, x1, x2)
    local n = 0
    for _, name in ipairs(names) do
      n = n + s.count_tiles_filtered({ name = name, area = { { x1, -RY }, { x2, RY } } })
    end
    return n
  end

  it("keeps stone OUT of the ENTIRE cold cap, right up to the divider", function()
    -- Cold zone is x > 100 (perp < -100). Zero stone anywhere east of the divider.
    assert.are.equal(0, count(field.STONE, 101, 450), "no stone anywhere on the cold cap")
    -- Not vacuous: the scanned zone is genuinely icy terrain.
    assert.is_true(count_tiles({ "cindra-cold-dust", "cindra-rough-ice", "cindra-deep-ice" }, 101, 450) > 0,
      "the scanned cold zone is real cold terrain, so the purity check is meaningful")
  end)

  it("keeps ice OUT of the ENTIRE hot + temperate zone (never west of the divider)", function()
    assert.are.equal(0, count(field.ICE, -350, 100), "no ice anywhere west of the divider")
    -- Not vacuous: the scanned hot zone is genuinely molten/building terrain.
    assert.is_true(count_tiles({ "cindra-lava-crust", "cindra-volcanic-warm", "cindra-terminator" }, -350, 100) > 0,
      "the scanned hot/temperate zone is real terrain, so the purity check is meaningful")
  end)

  it("keeps the TILE zones pure: hot tiles never east of the divider, cold never west", function()
    -- Hot molten tiles must never generate on the cold cap (x > 100)...
    assert.are.equal(0, count_tiles({ "cindra-hot-lava", "cindra-lava", "cindra-lava-crust",
                                      "cindra-volcanic-warm", "cindra-basalt" }, 101, 450),
      "no hot tiles east of the divider")
    -- ...and cold tiles must never generate on the hot side (x < -100).
    assert.are.equal(0, count_tiles({ "cindra-cold-dust", "cindra-rough-ice", "cindra-deep-ice" }, -450, -101),
      "no cold tiles west of the building band")
  end)

  -- 7. BAND-WIDE BOOTSTRAP ROCKS --------------------------------------------------
  it("scatters bootstrap rocks across the building band, not just near spawn (ci-9bb)", function()
    -- The building band is x in [-100, 100]. Present near spawn...
    local near = s.count_entities_filtered({
      name = field.ROCK, area = { { -100, -100 }, { 100, 100 } } })
    assert.is_true(near > 0, "bootstrap rocks scatter across the building band")
    -- ...and far down the ribbon (band-wide, not a spawn disk).
    local far = s.count_entities_filtered({
      name = field.ROCK, area = { { -100, 130 }, { 100, RY } } })
    assert.is_true(far > 0, "bootstrap rocks also generate far down the ribbon")
    -- Masked OUT of the hot margin (never past the building band on the perp axis).
    local outside = s.count_entities_filtered({
      name = field.ROCK, area = { { -300, -100 }, { -130, 100 } } })
    assert.are.equal(0, outside, "no rocks out past the building band (masked to the ribbon)")
  end)

  it("bounds the REAL cindra planet surface at creation (the runtime hook works)", function()
    local live = game.surfaces["cindra"]
      or (game.planets["cindra"] and game.planets["cindra"].create_surface())
    local mg = live.map_gen_settings
    assert.are.equal(900, mg.width, "the cindra surface is finite (900) on the perpendicular (X) axis")
    assert.is_true(mg.height == 0 or mg.height > 100000,
      "the ribbon is infinite along its long (Y) axis; got height=" .. tostring(mg.height))
  end)

  it("exposes real map-gen sliders (Stone + Ice only, no standalone volatiles)", function()
    for _, n in ipairs({ "cindra-stone", "cindra-ice" }) do
      local ctrl = prototypes.autoplace_control[n]
      assert.is_not_nil(ctrl, n .. " autoplace-control exists")
      assert.are.equal("resource", ctrl.category, n .. " is a resource slider")
    end
    assert.is_nil(prototypes.autoplace_control["cindra-volatiles"],
      "the standalone volatiles resource slider is gone (volatiles come from a processing recipe)")
    assert.is_nil(prototypes.entity["cindra-volatiles"],
      "there is no standalone volatiles resource entity")
    assert.is_not_nil(prototypes.item["cindra-volatiles"], "the volatiles item survives")
  end)

  it("marks the danger zone on the map: lethal tiles carry a distinct map_color (ci-4h7)", function()
    -- The engine normalises a map_color to 0..255 at runtime; normalise back to 0..1.
    local function mc(name)
      local c = prototypes.tile[name].map_color
      assert.is_not_nil(c, name .. " has a map_color")
      local scale = (c.r > 1 or c.g > 1 or c.b > 1) and 255 or 1
      return { c.r / scale, c.g / scale, c.b / scale }
    end
    local function dist(a, b)
      return math.abs(a[1] - b[1]) + math.abs(a[2] - b[2]) + math.abs(a[3] - b[3])
    end
    local center = mc("cindra-terminator")
    local lava, ice = mc("cindra-hot-lava"), mc("cindra-deep-ice")
    assert.is_true(dist(lava, center) > 0.6, "the hot-lava danger edge is distinct from the safe centre")
    assert.is_true(dist(ice, center) > 0.6, "the deep-ice danger edge is distinct from the safe centre")
    assert.is_true(dist(lava, terrain.map_color("cindra-hot-lava")) < 0.02, "hot-lava map_color follows terrain.lua")
    assert.is_true(dist(center, terrain.map_color("cindra-terminator")) < 0.02, "terminator map_color follows terrain.lua")
    assert.is_true(lava[1] > lava[2] and lava[1] > lava[3], "hot-lava reads red/orange on the map")
    assert.is_true(ice[3] > ice[1], "deep-ice reads cold (blue) on the map")
    -- The vanilla clone-source is NEVER recoloured (no cross-planet leakage).
    local vlava = prototypes.tile["lava"]
    if vlava and vlava.map_color then
      local vs = (vlava.map_color.r > 1 or vlava.map_color.g > 1 or vlava.map_color.b > 1) and 255 or 1
      assert.is_true(dist(lava, { vlava.map_color.r / vs, vlava.map_color.g / vs, vlava.map_color.b / vs }) > 0.05,
        "Cindra hot-lava has its own map_color; vanilla lava is untouched")
    end
  end)

  it("the ice field reads as ICY on the map: pale cyan/frost, distinct from stone AND iron ore (ci-9bb)", function()
    local ice = prototypes.entity["cindra-ice"].map_color
    assert.is_not_nil(ice, "the ice resource has a map_color")
    assert.is_true(ice.b >= 0.85 and ice.g >= 0.8, "ice map_color is a bright cyan/frost tone")
    assert.is_true(ice.b > ice.r and ice.g > ice.r, "ice map_color is cool (blue+green over red)")
    local stone = prototypes.entity["cindra-stone"].map_color
    assert.is_true(stone.r > stone.b, "sanity: stone is a warm tone")
    assert.is_true(ice.b > stone.b + 0.3, "ice is clearly icier/bluer than the warm stone patch")
    local iron = prototypes.entity["iron-ore"].map_color
    assert.is_true(ice.r + ice.g + ice.b > iron.r + iron.g + iron.b + 0.6,
      "ice map_color is markedly paler/brighter than iron ore's steel-blue")
    assert.is_true(ice.g > iron.g + 0.25, "ice map_color is more cyan than iron ore")
  end)

  it("the ice field is a single-product drop: ONLY the oxide chunk, no volatiles (ci-4xx)", function()
    local products = prototypes.entity["cindra-ice"].mineable_properties.products
    local names = {}
    for _, p in ipairs(products) do names[p.name] = true end
    assert.is_true(names["oxide-asteroid-chunk"], "the ice field still yields the vanilla oxide chunk")
    assert.is_nil(names["cindra-volatiles"],
      "mining the ice field must NOT drop volatiles -- they are a processing output now")
    assert.are.equal(1, #products,
      "the ice field is a single-product resource (just the oxide chunk)")
  end)
end)
